ext('c10_sst_ch23',[
C("🌳","वनों का महत्व",["ऑक्सीजन और वर्षा","मिट्टी का संरक्षण","आजीविका और औषधियाँ","जैव विविधता का घर"],"वन हमारे जीवन का आधार हैं। पेड़ कार्बन डाइऑक्साइड सोखकर ऑक्सीजन देते हैं और वर्षा लाने में मदद करते हैं। जड़ें मिट्टी को बाँधकर कटाव और बाढ़ से बचाती हैं। जंगलों से लकड़ी, फल, शहद, लाख और औषधीय पौधे मिलते हैं, जिनसे करोड़ों लोगों की आजीविका चलती है। वन असंख्य पशु-पक्षियों और पौधों का घर भी हैं। इसलिए वनों का संरक्षण पूरे पर्यावरण के संतुलन के लिए ज़रूरी है।"),
Q("वन बाढ़ और मिट्टी के कटाव को कैसे रोकते हैं?","पेड़ों की जड़ें मिट्टी को बाँधती हैं और वर्षा का पानी धीरे-धीरे ज़मीन में जाने देती हैं","सोचिए... जड़ें मिट्टी को पकड़कर रखती हैं और पत्तियाँ बारिश की तेज़ बूँदों को धीमा करती हैं। इससे पानी बहकर तेज़ी से नदियों में नहीं जाता, और बाढ़ व कटाव कम होता है।"),
C("📉","वनों और जीवों के घटने के कारण",["कृषि का विस्तार","औद्योगीकरण और खनन","बड़ी परियोजनाएँ और बाँध","शिकार और अवैध कटाई"],"भारत में वनों और वन्य जीवों की संख्या घटने के कई कारण हैं। खेती के लिए जंगल साफ़ किए गए। उद्योग, खनन, सड़कों और बाँध जैसी बड़ी परियोजनाओं के लिए भी वन कटे। अवैध कटाई और शिकार ने बाघ, गैंडा जैसे जीवों को ख़तरे में डाल दिया। जंगल की आग, अति चराई और बढ़ती आबादी का दबाव भी इसके कारण हैं। आवास नष्ट होने से जीवों के भोजन और प्रजनन के स्थान समाप्त हो जाते हैं।"),
Q("वन्य जीवों के घटने के दो मुख्य कारण बताइए।","आवास का नष्ट होना (वनों की कटाई) और अवैध शिकार","कारण सोचिए... जंगल कटने से जीवों का घर ख़त्म होता है और शिकार से उनकी संख्या तेज़ी से घटती है। ये दोनों कारण मिलकर प्रजातियों को संकट में डालते हैं।"),
C("🗂️","प्रजातियों की श्रेणियाँ",["सामान्य प्रजातियाँ","संकटग्रस्त प्रजातियाँ","सुभेद्य प्रजातियाँ","दुर्लभ और स्थानिक"],"आई यू सी एन के अनुसार जीवों को अलग-अलग श्रेणियों में बाँटा गया है। संकटग्रस्त प्रजातियाँ वे हैं जो विलुप्त होने के कगार पर हैं, जैसे बाघ और गैंडा। सुभेद्य प्रजातियाँ वे हैं जिनकी संख्या घट रही है और यदि ख़तरे के कारक न बदले तो वे संकटग्रस्त हो जाएँगी। दुर्लभ प्रजातियों की संख्या कम होती है। स्थानिक प्रजातियाँ केवल किसी ख़ास क्षेत्र में मिलती हैं। इन श्रेणियों से संरक्षण की प्राथमिकता तय होती है।"),
Q("संकटग्रस्त और सुभेद्य प्रजाति में क्या अंतर है?","संकटग्रस्त विलुप्ति के कगार पर हैं; सुभेद्य की संख्या घट रही है और भविष्य में संकटग्रस्त हो सकती है","अंतर सोचिए... संकटग्रस्त प्रजाति अभी गंभीर ख़तरे में है। सुभेद्य प्रजाति उससे एक क़दम पहले है, जिसकी संख्या घट रही है।"),
C("⚖️","संरक्षण: क़ानून और परियोजनाएँ",["वन्य जीव संरक्षण अधिनियम 1972","प्रोजेक्ट टाइगर 1973","राष्ट्रीय उद्यान और अभयारण्य","जैव मंडल आरक्षित क्षेत्र"],"भारत सरकार ने वन्य जीवों के संरक्षण के लिए उन्नीस सौ बहत्तर में वन्य जीव संरक्षण अधिनियम बनाया। इसमें शिकार पर रोक और संकटग्रस्त जीवों की सुरक्षा के प्रावधान हैं। उन्नीस सौ तिहत्तर में प्रोजेक्ट टाइगर शुरू हुआ, जिससे बाघों की संख्या बढ़ाने में मदद मिली। राष्ट्रीय उद्यान, वन्य जीव अभयारण्य और जैव मंडल आरक्षित क्षेत्र बनाए गए ताकि जीवों को सुरक्षित आवास मिल सके।"),
Q("प्रोजेक्ट टाइगर कब शुरू हुआ और इसका उद्देश्य क्या था?","1973 में; बाघों की संख्या बचाना और बढ़ाना","तिथि याद कीजिए... यह उन्नीस सौ तिहत्तर में शुरू हुआ। उद्देश्य बाघों के प्राकृतिक आवास की रक्षा और उनकी संख्या बढ़ाना था।"),
C("🏞️","वनों के प्रकार (प्रशासन के अनुसार)",["आरक्षित वन: सबसे सुरक्षित","रक्षित वन: सीमित अनुमति","अवर्गीकृत वन","समुदाय के उपयोग वाले"],"प्रशासन की दृष्टि से वनों को तीन भागों में बाँटा जाता है। आरक्षित वन सबसे अधिक संरक्षित हैं और इनमें आम लोगों का प्रवेश तथा चराई वर्जित है। रक्षित वनों में कुछ शर्तों के साथ सीमित उपयोग की अनुमति होती है। अवर्गीकृत वन वे हैं जिनमें सरकार और व्यक्तियों के पास भूमि होती है और उपयोग पर कोई विशेष रोक नहीं होती। अधिकतर आरक्षित वन राज्य सरकार के अधीन होते हैं।"),
Q("आरक्षित वन और रक्षित वन में अंतर बताइए।","आरक्षित वन में आम प्रवेश/चराई वर्जित है; रक्षित वन में सीमित उपयोग की अनुमति होती है","अंतर सोचिए... आरक्षित वन ज़्यादा सख़्त संरक्षण में हैं और आम लोग उसमें प्रवेश नहीं कर सकते। रक्षित वन में शर्तों के साथ छूट मिलती है।"),
C("🤝","जन-भागीदारी से संरक्षण",["बिश्नोई समाज","चिपको आंदोलन","संयुक्त वन प्रबंधन","पवित्र उपवन"],"वनों का संरक्षण केवल क़ानून से नहीं, लोगों की भागीदारी से होता है। राजस्थान का बिश्नोई समाज सदियों से पेड़ों और काले हिरण की रक्षा करता आया है। उत्तराखंड में चिपको आंदोलन में लोग पेड़ों से लिपट गए ताकि उन्हें कटने से बचाया जा सके। संयुक्त वन प्रबंधन में गाँव के लोग वन विभाग के साथ मिलकर जंगल की देखभाल करते हैं। कई जगह पवित्र उपवन धार्मिक आस्था के कारण सुरक्षित हैं।"),
Q("चिपको आंदोलन क्या था?","पेड़ों को कटने से बचाने के लिए लोगों का उनसे लिपट जाना, उत्तराखंड का आंदोलन","याद कीजिए... गाँव की महिलाएँ और लोग पेड़ों से चिपक गए ताकि ठेकेदार उन्हें काट न सकें। यह पर्यावरण संरक्षण का प्रसिद्ध जन आंदोलन है।"),
C("🐯","बिहार का वन संसाधन",["वाल्मीकि टाइगर रिज़र्व","गंगा डॉल्फ़िन अभयारण्य","कैमूर और राजगीर","वृक्षारोपण योजनाएँ"],"बिहार में वाल्मीकि टाइगर रिज़र्व राज्य का एकमात्र बाघ अभयारण्य है। भागलपुर के पास विक्रमशिला गंगा डॉल्फ़िन अभयारण्य देश का एकमात्र डॉल्फ़िन अभयारण्य है। कैमूर और राजगीर के वनों में भी जैव विविधता मिलती है। राज्य सरकार वृक्षारोपण और जल-जीवन-हरियाली जैसी योजनाएँ चला रही है। हम भी अपने घर और विद्यालय में पेड़ लगाकर और उनकी देखभाल करके योगदान दे सकते हैं।"),
C("✍️","परीक्षा के सुझाव",["परिभाषा और कारण","क़ानून, वर्ष और परियोजना","प्रकार और अंतर","बिहार के उदाहरण"],"इस अध्याय में वर्ष और नाम याद रखना ज़रूरी है, जैसे उन्नीस सौ बहत्तर और उन्नीस सौ तिहत्तर। वनों के प्रकार और प्रजातियों की श्रेणियों की तालिका बनाइए। उत्तर में बिहार के वाल्मीकि टाइगर रिज़र्व और डॉल्फ़िन अभयारण्य का उदाहरण दीजिए। अंत में अपने स्तर पर सुझाव लिखिए, जैसे पेड़ लगाना, प्लास्टिक कम करना और जागरूकता फैलाना।"),
],7)
